import { json, error } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { getDb } from '$lib/server/db';
import { pushSubscriptions } from '$lib/server/db';
import { eq, and } from 'drizzle-orm';

export const GET: RequestHandler = async ({ params, url }) => {
  const flightId = parseInt(params.flightId, 10);
  if (isNaN(flightId)) throw error(400, 'Invalid flightId');

  const endpoint = url.searchParams.get('endpoint');
  if (!endpoint) throw error(400, 'Missing endpoint');

  const db = getDb();
  const rows = await db
    .select({ id: pushSubscriptions.id })
    .from(pushSubscriptions)
    .where(and(eq(pushSubscriptions.flightId, flightId), eq(pushSubscriptions.endpoint, endpoint)))
    .limit(1);

  return json({ subscribed: rows.length > 0 });
};

// Server-only database module — SvelteKit enforces $lib/server is never accessible client-side.
// Vite resolves @airways/database via alias in vite.config.ts → packages/database/index.ts.
// pg and drizzle-orm are marked as ssr.external so they're never bundled.

export { db, getDb, guernseyTodayStr, guernseyTomorrowStr, isTerminalStatus } from '@airways/database';
export {
  flights,
  flightTimes,
  flightNotes,
  flightStatusHistory,
  weatherData,
  historicalWeather,
  airportDaylight,
  scraperLogs,
  aircraftPositions,
  airports,
  pushSubscriptions,
  notificationWatermark,
} from '@airways/database/schema';

import { env } from '$env/dynamic/private';
import { json } from '@sveltejs/kit';
import type { Handle, HandleServerError } from '@sveltejs/kit';
import { validateDebugToken } from '$lib/server/debug-helpers';

export const handle: Handle = async ({ event, resolve }) => {
  // Debug API auth — gate /api/debug/* behind Bearer token
  if (event.url.pathname.startsWith('/api/debug/')) {
    const auth = event.request.headers.get('authorization');
    if (!validateDebugToken(auth, env.DEBUG_API_TOKEN)) {
      return json({ error: 'Unauthorized' }, { status: 401 });
    }
  }

  const response = await resolve(event);
  if (
    event.request.method === 'GET' &&
    (response.headers.get('content-type') ?? '').includes('text/html')
  ) {
    // If the request carries the recently-viewed cookie the response is personalised,
    // so it must not be stored in a shared cache (CDN). Non-cookied visitors (first-time
    // or cleared) are safe to cache publicly.
    const personalized = event.request.headers.get('cookie')?.includes('rv=') ?? false;
    response.headers.set(
      'Cache-Control',
      personalized
        ? 'private, max-age=0'
        : 'public, max-age=0, s-maxage=30, stale-while-revalidate=60',
    );
  }
  return response;
};

export const handleError: HandleServerError = ({ error, event, status }) => {
  // Log server-side errors with context (avoids leaking stack traces to the client)
  const message = error instanceof Error ? error.message : 'Unknown error';
  console.error(`[server error] ${status} on ${event.url.pathname}: ${message}`);

  // Return a safe, generic message to the client
  return {
    message: status === 404 ? 'Not found' : 'An unexpected error occurred',
  };
};

import { json, error } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { getDb } from '$lib/server/db';
import { pushSubscriptions } from '$lib/server/db';
import { eq, and } from 'drizzle-orm';

export const POST: RequestHandler = async ({ request }) => {
  let body: { subscription: PushSubscription; flightId: number; flightCode: string; flightDate: string };
  try {
    body = await request.json();
  } catch {
    throw error(400, 'Invalid JSON');
  }

  const { subscription, flightId, flightCode, flightDate } = body;
  if (!subscription?.endpoint || !flightId || !flightCode || !flightDate) {
    throw error(400, 'Missing required fields');
  }

  const db = getDb();
  await db
    .insert(pushSubscriptions)
    .values({
      endpoint: subscription.endpoint,
      subscription: subscription as unknown as Record<string, unknown>,
      flightId,
      flightCode,
      flightDate,
    })
    .onConflictDoUpdate({
      target: [pushSubscriptions.endpoint, pushSubscriptions.flightId],
      set: {
        subscription: subscription as unknown as Record<string, unknown>,
        flightCode,
        flightDate,
      },
    });

  return json({ ok: true });
};

export const DELETE: RequestHandler = async ({ request }) => {
  let body: { endpoint: string; flightId: number };
  try {
    body = await request.json();
  } catch {
    throw error(400, 'Invalid JSON');
  }

  const { endpoint, flightId } = body;
  if (!endpoint || !flightId) {
    throw error(400, 'Missing required fields');
  }

  const db = getDb();
  await db
    .delete(pushSubscriptions)
    .where(and(eq(pushSubscriptions.endpoint, endpoint), eq(pushSubscriptions.flightId, flightId)));

  return json({ ok: true });
};

